    private lazy val groupCount: Int = m.groupCount()

    private lazy val matches: List[String] = (for {
      n <- 1 to groupCount
      group = Try(m.group(n))
      if group.isSuccess
    } yield group.get).toList

    override lazy val toString: String = s"match: $find, matches: $matches"
